  if (g.floor > 0.05) g.floor = 0.05;
  var thrOn = Math.max(0.012, g.floor * 3 + 0.008);
  var thrOff = thrOn * 0.5;
  var impulse = peak / (rms + 1e-6) > 6;
  if (rms >= thrOn && !impulse) g.run++;
  else if (rms < thrOff) g.run = 0;
  if (g.run >= 2) { g.on = true; g.hang = 200; }
  else if (g.on) {
    g.hang -= dtMs;
    if (g.hang <= 0 || rms < thrOff) g.on = false;
  }
